-- PT113-S4-Q14. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT113-S4-Q14$batch12$ AND q.stimulus=$batch12$The fact that politicians in a certain country are trying to reduce government spending does not by itself explain why they have voted to eliminate all government-supported scholarship programs. Government spending could have been reduced even more if instead they had cut back on military spending.$batch12$ AND q.prompt=$batch12$Which one of the following arguments is most similar in its reasoning to the argument above?$batch12$ AND q.correct_choice=$batch12$E$batch12$) THEN RAISE EXCEPTION 'Question changed: PT113-S4-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT113-S4-Q14$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S4-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT113-S4-Q14$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Wanting to cut spending doesn't by itself explain why politicians eliminated scholarships.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Cutting military spending would have reduced spending even more.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A goal doesn't explain a choice when another option would have served that same goal better.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Goal X doesn't explain choice Y, because another choice serves X better.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT113-S4-Q14$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This points to Phyllis's past habits, not a better route to the same goal.$batch12$), ($batch12$B$batch12$, $batch12$This uses other students who manage fine. No better option for a goal.$batch12$), ($batch12$C$batch12$, $batch12$This is the popular trap. It names something Sallie and Jim could have done to fix the problem. The original names a better way to reach the stated goal.$batch12$), ($batch12$D$batch12$, $batch12$This explains the cats with other people's unwillingness.$batch12$), ($batch12$E$batch12$, $batch12$Becoming famous doesn't explain choosing acting, because writing or directing is an easier path to fame. Same move.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT113-S4-Q14$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
